export type VendorChange = { "kind": "rename", name: string, } | { "kind": "defaultItem", key: string | null, } | { "kind": "mergeInto", into: string, } | { "kind": "delete" };

/**
 * A vendor the combo box suggests.
 */
export type VendorOption = { name: string, 
/**
 * `2 documents`.
 */
detail: string, };

export type VendorView = { id: string, name: string, 
/**
 * `2 documents · KZ 169`.
 */
detail: string, defaultItemKey: string | null, 
/**
 * No document uses it.
 */
unused: boolean, };

export type VendorsView = { vendors: Array<VendorView>, items: Array<ItemOption>, };

export type YearCheckView = { year: number, open: boolean, 
/**
 * In the order a run asks them.
 */
questions: Array<CheckQuestion>, 
/**
 * `14 Nov 2026`; None before the first completed run.
 */
lastRun: string | null, 
/**
 * 31 Dec of the year has passed.
 */
yearOver: boolean, 
/**
 * `Year check: last run 2 Jun 2026 · run it again after 31 Dec`, for the tax year page.
 */
line: string, 
/**
 * What Close Year asks first; None when a run after 31 Dec is done or there is nothing to ask.
 */
closePrompt: string | null, };

export type YearPage = { year: number, ruleset: string, state: YearState, 
/**
 * `€1,228.40`.
 */
total: string, 
/**
 * `Draft · 2 invoices and 1 answer missing`, `Ready to close`.
 */
progress: string, 
/**
 * Done facts out of all, 0–100.
 */
progressPercent: number, 
/**
 * Shown when the total is below the Werbungskostenpauschale.
 */
pauschaleNote: string | null, questions: Array<QuestionView>, attention: Array<AttentionView>, kennzahlen: Array<KennzahlView>, months: Array<MonthView>, archived: number, };

export type YearRow = { id: string, kind: RowKind, title: string, 
/**
 * `10 Nov · 60 % of €22.48`.
 */
detail: string, 
/**
 * What it counts, `€13.49`.
 */
amount: string, draft: boolean, 
/**
 * The purchase year of a depreciation slice counted in a later year.
 */
carriedFrom: number | null, kz: string, 
/**
 * An amount without its evidence PDF.
 */
attach: boolean, };

export type YearState = "open" | "closed";

export type YearSummary = { year: number, total: string, progress: string, progressPercent: number, };
